window.VeilGardeData.files["Scripts"] = {"group":"Scripts","files":[{"path":"Scripts/audio-corpus.sh","status":"added","lang":"shell","hunks":[[1,0,1,51]],"header":{"lines":[2,14],"style":"hash","what":[3,4],"pin":[8,13],"in":[5,5],"out":[6,7]},"marks":[],"first":1907,"scopes":[],"old":"","new":"#!/usr/bin/env bash\n# SPDX-License-Identifier: GPL-3.0-only\n# WHAT: Render the audio acceptance's speech corpus with macOS's own voices: seven standard voices\n#       reading eight fixed sentences each, one AIFF an utterance, into <out>/speech/.\n# IN:   --out <folder> (required). A voice this Mac does not have is skipped and named.\n# OUT:  <out>/speech/<voice>_<n>.aiff, mono 22.05 kHz 16-bit, a line per voice on stderr. Measured\n#       2026-11-08: 56 utterances of 7.9 to 10.6 s, one under the speech profile's 8 s admission.\n# PIN:  The voices and the sentences are fixed here, before any acceptance number: Samantha,\n#       Daniel, Fred, Karen, Moira, Rishi, Tessa; sentences 1 to 8 below, unchanged once measured.\n#       `say` renders through the system's speech engine, so a macOS update may change the samples;\n#       the acceptance's report names the date it ran.\n#\n#   Scripts/audio-corpus.sh --out \"$VEILGARDE_WORK_AREA/audio/corpus\"\n#\nset -euo pipefail\n\nout=\"\"\nwhile [ $# -gt 0 ]; do\n    case \"$1\" in\n        --out) out=\"$2\"; shift 2 ;;\n        *) echo \"audio-corpus: unknown argument $1\" >&2; exit 64 ;;\n    esac\ndone\n[ -n \"$out\" ] || { echo \"audio-corpus: --out <folder> is required\" >&2; exit 64; }\nmkdir -p \"$out/speech\"\n\nvoices=(Samantha Daniel Fred Karen Moira Rishi Tessa)\nsentences=(\n    \"The river carried the last of the autumn leaves past the old mill, where a heron stood in the shallows and waited for the light to change before it moved again.\"\n    \"Every morning the baker opened the shutters at six, set the first loaves on the counter, and wrote the day's soup on a small slate beside the door for anyone passing.\"\n    \"The train left the coast an hour late, climbed slowly through the hills in the rain, and reached the city just as the street lamps came on along the wide avenue.\"\n    \"She tuned the piano by ear, one string at a time, listening for the slow beat between two notes to fade until the chord rang clear across the empty hall.\"\n    \"Four friends rented a small boat for the weekend, argued about the map for most of the morning, and finally found the island by following a line of gulls.\"\n    \"The library kept its oldest maps in a cool room downstairs, and a visitor could ask to see them on Thursday afternoons if they promised to wear the cotton gloves.\"\n    \"A storm crossed the valley before dawn, knocked out the power for two hours, and left the orchard covered in small green apples that the children gathered in baskets.\"\n    \"In the workshop the clockmaker laid out every gear on a soft cloth, cleaned each one with a fine brush, and then put the whole movement back together without a pause.\"\n)\n\nfor voice in \"${voices[@]}\"; do\n    if ! say -v '?' | grep -q \"^${voice}[[:space:]]\"; then\n        echo \"audio-corpus: no voice ${voice} on this Mac, skipped\" >&2\n        continue\n    fi\n    n=1\n    for sentence in \"${sentences[@]}\"; do\n        say -v \"$voice\" -o \"$out/speech/$(echo \"$voice\" | tr 'A-Z' 'a-z')_${n}.aiff\" \"$sentence\"\n        n=$((n + 1))\n    done\n    echo \"audio-corpus: ${voice}: ${#sentences[@]} utterances\" >&2\ndone\necho \"audio-corpus: $(ls \"$out/speech\" | grep -c '\\.aiff$') utterances in $out/speech\" >&2\n"},{"path":"Scripts/cli.sh","status":"added","lang":"shell","hunks":[[1,0,1,90]],"header":{"lines":[2,21],"style":"hash","what":[3,5],"pin":[12,20],"in":[6,11],"out":null},"marks":[],"first":1907,"scopes":[],"old":"","new":"#!/usr/bin/env bash\n# SPDX-License-Identifier: GPL-3.0-only\n# WHAT: Run the veilgarde CLI from a checkout: build it when a source is newer than the binary\n#       (VeilGarde's or Frigate's), put MLX's Metal library beside it the first time, then hand\n#       every argument to veilgarde.\n# IN:   Arguments go to veilgarde unchanged.\n#       VEILGARDE_CONFIG=release   build and run the release binary (default debug); use it for\n#                                  anything that trains, extracts at scale or measures\n#       VEILGARDE_BUILD=always     run swift build even when nothing looks newer\n#       VEILGARDE_SKIP_BUILD=1     run the binary that is already built\n#       VEILGARDE_METALLIB=rebuild reinstall mlx.metallib (after a Frigate/MLX update)\n# PIN:  Never changes directory, so relative paths in the arguments resolve against yours. Build\n#       chatter goes to stderr and veilgarde's own output to stdout, so\n#       `Scripts/cli.sh route x.jpg --json | jq` stays clean. The metallib is only installed when\n#       it is missing (build-metallib.sh also copies it into the test bundles, which must be\n#       stripped of it again before the next test build: a copy breaks the bundle's re-sign).\n#\n#   Scripts/cli.sh doctor\n#   Scripts/cli.sh route photo.jpg --json\n#   VEILGARDE_CONFIG=release Scripts/cli.sh train all\n#\nset -euo pipefail\n\nsource_path=\"${BASH_SOURCE[0]}\"\nwhile [ -L \"$source_path\" ]; do\n    target=\"$(readlink \"$source_path\")\"\n    case \"$target\" in\n        /*) source_path=\"$target\" ;;\n        *) source_path=\"$(dirname \"$source_path\")/$target\" ;;\n    esac\ndone\nREPO_ROOT=\"$(cd \"$(dirname \"$source_path\")/..\" && pwd)\"\n# Frigate, the vendored MLX stack, is taken by path: VEILGARDE_FRIGATE_DIR, else a checkout beside this repo\n# (https://github.com/rao-studios/Frigate). A machine's own settings, kept in a gitignored Scripts/lib.sh, come first.\n[ -f \"$REPO_ROOT/Scripts/lib.sh\" ] && source \"$REPO_ROOT/Scripts/lib.sh\"\nVEILGARDE_FRIGATE_DIR=\"${VEILGARDE_FRIGATE_DIR:-$REPO_ROOT/../Frigate}\"\nif [ ! -f \"$VEILGARDE_FRIGATE_DIR/Package.swift\" ]; then\n    echo \"veilgarde: no Frigate at $VEILGARDE_FRIGATE_DIR: check it out beside this repo, or set VEILGARDE_FRIGATE_DIR\" >&2\n    exit 69\nfi\nexport VEILGARDE_FRIGATE_DIR=\"$(cd \"$VEILGARDE_FRIGATE_DIR\" && pwd)\"\nexport GIT_LFS_SKIP_SMUDGE=1    # Frigate's LFS fixtures break SwiftPM checkouts otherwise\n\nconfig=\"${VEILGARDE_CONFIG:-debug}\"\ncase \"$config\" in\n    debug | release) ;;\n    *)\n        echo \"cli.sh: VEILGARDE_CONFIG must be debug or release, not '$config'\" >&2\n        exit 64\n        ;;\nesac\n\n# SwiftPM's build system decides where products land (.build/out/Products/<Config> today): ask it.\nbin_dir=\"$(swift build --package-path \"$REPO_ROOT\" -c \"$config\" --show-bin-path 2>/dev/null)\"\nbinary=\"$bin_dir/veilgarde\"\n\nwatched=()\nfor path in \"$REPO_ROOT/Sources\" \"$REPO_ROOT/Package.swift\" \\\n    \"$VEILGARDE_FRIGATE_DIR/Sources\" \"$VEILGARDE_FRIGATE_DIR/Package.swift\"; do\n    [ -e \"$path\" ] && watched+=(\"$path\")\ndone\n\nneeds_build() {\n    [ \"${VEILGARDE_BUILD:-}\" = \"always\" ] && return 0\n    [ -x \"$binary\" ] || return 0\n    [ -n \"$(find \"${watched[@]}\" -newer \"$binary\" -type f -not -name '._*' -print -quit 2>/dev/null)\" ]\n}\n\nif [ -z \"${VEILGARDE_SKIP_BUILD:-}\" ] && needs_build; then\n    echo \"cli.sh: building veilgarde ($config)\" >&2\n    if ! swift build --package-path \"$REPO_ROOT\" -c \"$config\" --product veilgarde -q >&2; then\n        echo \"cli.sh: swift build -c $config failed\" >&2\n        exit 1\n    fi\n    bin_dir=\"$(swift build --package-path \"$REPO_ROOT\" -c \"$config\" --show-bin-path)\"\n    binary=\"$bin_dir/veilgarde\"\n    touch \"$binary\"\nfi\nif [ ! -x \"$binary\" ]; then\n    echo \"cli.sh: no veilgarde binary in $bin_dir\" >&2\n    echo \"  build it first, or unset VEILGARDE_SKIP_BUILD\" >&2\n    exit 1\nfi\n\nif [ ! -f \"$bin_dir/mlx.metallib\" ] || [ \"${VEILGARDE_METALLIB:-}\" = \"rebuild\" ]; then\n    echo \"cli.sh: installing mlx.metallib beside the $config binary\" >&2\n    \"$REPO_ROOT/build-metallib.sh\" \"$config\" > /dev/null\nfi\n\nexec \"$binary\" \"$@\"\n"},{"path":"Scripts/site.command","status":"added","lang":"shell","hunks":[[1,0,1,18]],"header":{"lines":[2,7],"style":"hash","what":[3,4],"pin":[5,7],"in":null,"out":null},"marks":[],"first":1907,"scopes":[],"old":"","new":"#!/bin/zsh\n# SPDX-License-Identifier: GPL-3.0-only\n# WHAT: Open VeilGarde's site, the change explorer and its chapters in Docs/site, in the default browser.\n#       Double-click it in Finder, or run Scripts/site.command from anywhere.\n# PIN:  The site is plain HTML read from file://, so nothing is built or served. Docs/site/src/build.sh\n#       regenerates its data and checks every page. The one thing this writes is Docs/site/local/ask.js, the\n#       ask orb's Mistral key copied from this Mac, which git ignores.\nset -euo pipefail\ncd \"$(dirname \"$0\")/..\"\npage=\"Docs/site/index.html\"\nif [[ ! -f \"$page\" ]]; then\n  echo \"site.command: no $page under $(pwd)\" >&2\n  exit 1\nfi\n# The ask orb uses this Mac's Mistral key, when it holds one, copied to a gitignored file.\npython3 -I Docs/site/src/askkey.py || true\nopen \"$page\"\necho \"opened $(pwd)/$page\"\n"}]};
